const upsertProjectDocument = `-- name: UpsertProjectDocument :one
INSERT INTO project_documents (project_id, id, kind, logical_name, text_content)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (project_id, kind, logical_name)
DO UPDATE SET text_content = EXCLUDED.text_content,
    updated_at = clock_timestamp(), version = project_documents.version + 1
RETURNING id
`

type UpsertProjectDocumentParams struct {
	ProjectID   pgtype.UUID `json:"project_id"`
	ID          pgtype.UUID `json:"id"`
	Kind        string      `json:"kind"`
	LogicalName string      `json:"logical_name"`
	TextContent pgtype.Text `json:"text_content"`
}

func (q *Queries) UpsertProjectDocument(ctx context.Context, arg UpsertProjectDocumentParams) (pgtype.UUID, error) {
	row := q.db.QueryRow(ctx, upsertProjectDocument,
		arg.ProjectID,
		arg.ID,
		arg.Kind,
		arg.LogicalName,
		arg.TextContent,
	)
	var id pgtype.UUID
	err := row.Scan(&id)
	return id, err
}

const upsertReviewDecision = `-- name: UpsertReviewDecision :exec
INSERT INTO review_decisions (project_id, review_id, item_key, decision,
    actor_user_id, payload)
VALUES ($1, $2, $3, 'kept', $4, $5)
ON CONFLICT (project_id, review_id, item_key)
DO UPDATE SET payload = EXCLUDED.payload, actor_user_id = EXCLUDED.actor_user_id,
    updated_at = clock_timestamp(), version = review_decisions.version + 1
`

type UpsertReviewDecisionParams struct {
	ProjectID   pgtype.UUID `json:"project_id"`
	ReviewID    pgtype.UUID `json:"review_id"`
	ItemKey     string      `json:"item_key"`
	ActorUserID pgtype.UUID `json:"actor_user_id"`
	Payload     []byte      `json:"payload"`
}

func (q *Queries) UpsertReviewDecision(ctx context.Context, arg UpsertReviewDecisionParams) error {
	_, err := q.db.Exec(ctx, upsertReviewDecision,
		arg.ProjectID,
		arg.ReviewID,
		arg.ItemKey,
		arg.ActorUserID,
		arg.Payload,
	)
	return err
}

