func (q *Queries) UpsertVolume(ctx context.Context, arg UpsertVolumeParams) error {
	_, err := q.db.Exec(ctx, upsertVolume,
		arg.ProjectID,
		arg.StoryID,
		arg.ID,
		arg.Number,
		arg.Title,
		arg.Outline,
	)
	return err
}
